func testActivityTUIModel() activityModel {
	vp := viewport.New(80, 3)
	vp.SetContent(strings.Join([]string{
		"line 1",
		"line 2",
		"line 3",
		"line 4",
		"line 5",
		"line 6",
	}, "\n"))

	return activityModel{
